  Rooted<JSObject*> obj(cx);
  CreateJSMessage(aMessage, cx, obj);
  Rooted<Value> message(cx, ObjectValue(*obj));
  MutableHandle<Value> handle(&message);
  mListener->OnMessageAdded(handle);
}

